from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import product
import heapq
from collections import Counter


def _dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows_by_name = {
        name: {row["version"]: row for row in rows}
        for name, rows in packages.items()
    }
    candidates = []
    for name in names:
        versions = sorted(rows_by_name[name])
        if name in pins:
            versions = [v for v in versions if v == pins[name]]
        versions = [v for v in versions if v not in blocked.get(name, [])]
        candidates.append([-1] + versions)

    best_vector = None
    best = None
    for values in product(*candidates):
        installed = dict(zip(names, values))
        if any(installed.get(name, -1) < 0 or
               not bounds[0] <= installed[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        graph = {}
        valid = True
        for name, version in installed.items():
            if version < 0:
                continue
            row = rows_by_name[name][version]
            deps = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_version = installed.get(target, -1)
                if target_version < 0 or not dep["min"] <= target_version <= dep["max"]:
                    valid = False
                    break
                deps.append(target)
            if not valid:
                break
            graph[name] = deps
        if not valid:
            continue

        # Installed packages must be exactly the active closure of the roots.
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(graph.get(name, []))
        if any(version >= 0 and name not in reachable
               for name, version in installed.items()):
            continue

        finished, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            for other in graph.get(name, []):
                if not visit(other):
                    return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in graph):
            continue
        vector = tuple(installed[name] for name in names)
        if (best_vector is None or
                (vector > best_vector if preference == "maximum"
                 else vector < best_vector)):
            best_vector = vector
            best = {name: version for name, version in installed.items()
                    if version >= 0}
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _build_dependency(preference, name_order):
    return lambda data: _dependency_solver(data, preference, name_order)


def _component_06(data):
    mode = data["rounding"]

    def rounded(numerator, denominator=10000):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    winners = {}
    cutoff = data.get("cutoff", 10**9)
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None
    n = len(jobs)
    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        selected = [jobs[i] for i in range(n) if mask & (1 << i)]
        ids = {job["id"] for job in selected}
        if ids & blocked or not mandatory.issubset(ids):
            continue
        counts = Counter(job["group"] for job in selected)
        if any(not low <= counts[group] <= high
               for group, (low, high) in quotas.items()):
            continue
        active_ends = []
        valid = True
        for job in sorted(selected, key=lambda row: (row["start"], row["end"])):
            while active_ends and active_ends[0] <= job["start"]:
                heapq.heappop(active_ends)
            heapq.heappush(active_ends, job["end"])
            if len(active_ends) > 2:
                valid = False
                break
        if not valid:
            continue
        sorted_ids = sorted(ids)
        value = sum(job["value"] for job in selected)
        if (best_ids is None or value > best_value or
                (value == best_value and sorted_ids < best_ids)):
            best_ids, best_value = sorted_ids, value
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    indexes = {node: i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    def add_visit(mask, node):
        if node in indexes:
            mask |= 1 << indexes[node]
        return mask

    source = data["source"]
    start_mask = add_visit(0, source)
    start = data["start"]
    initial = (source, start_mask, data["coupons"])
    best = {initial: start}
    queue = [(start, source, start_mask, data["coupons"])]
    while queue:
        arrival, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if best.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [(edge["duration"], coupons)]
            if coupons:
                durations.append((max(2, edge["duration"] - edge.get("discount", 0)), coupons - 1))
            for duration, remaining in durations:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = add_visit(mask, next_node)
                next_state = (next_node, next_mask, remaining)
                if next_time < best.get(next_state, float("inf")):
                    best[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask, remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": _build_dependency("maximum", "ascending"),
    "component_02": _build_dependency("minimum", "ascending"),
    "component_03": _build_dependency("maximum", "descending"),
    "component_04": _build_dependency("minimum", "descending"),
    "component_05": _build_dependency("maximum", "ascending"),
    "component_06": _component_06,
    "component_07": _component_07,
    "component_08": _component_08,
}
